const extendedVerses = [{"number":4,"greek":"Ἀρὰμ δὲ ἐγέννησε τὸν Ἀμιναδάβ, Ἀμιναδὰβ δὲ ἐγέννησε τὸν Ναασσών, Ναασσὼν δὲ ἐγέννησε τὸν Σαλμών,","en":"Aram fathered Amminadab, Amminadab fathered Nahshon, and Nahshon fathered Salmon.","ko":"아람은 아미나답을, 아미나답은 나손을, 나손은 살몬을 낳았습니다."},{"number":5,"greek":"Σαλμὼν δὲ ἐγέννησε τὸν Βόοζ ἐκ τῆς Ῥαχάβ, Βόοζ δὲ ἐγέννησε τὸν Ὠβὴδ ἐκ τῆς Ῥούθ, Ὠβὴδ δὲ ἐγέννησε τὸν Ἰεσσαί,","en":"Salmon fathered Boaz by Rahab, Boaz fathered Obed by Ruth, and Obed fathered Jesse.","ko":"살몬은 라합에게서 보아스를, 보아스는 룻에게서 오벳을, 오벳은 이새를 낳았습니다."},{"number":6,"greek":"Ἰεσσαὶ δὲ ἐγέννησε τὸν Δαβὶδ τὸν βασιλέα. Δαβὶδ δὲ ὁ βασιλεὺς ἐγέννησε τὸν Σολομῶνα ἐκ τῆς τοῦ Οὐρίου,","en":"Jesse fathered David the king. David the king fathered Solomon by the wife of Uriah.","ko":"이새는 다윗 왕을 낳았고, 다윗 왕은 우리야의 아내에게서 솔로몬을 낳았습니다."},{"number":7,"greek":"Σολομὼν δὲ ἐγέννησε τὸν Ῥοβοάμ, Ῥοβοὰμ δὲ ἐγέννησε τὸν Ἀβιά, Ἀβιὰ δὲ ἐγέννησε τὸν Ἀσά,","en":"Solomon fathered Rehoboam, Rehoboam fathered Abijah, and Abijah fathered Asa.","ko":"솔로몬은 르호보암을, 르호보암은 아비야를, 아비야는 아사를 낳았습니다."},{"number":8,"greek":"Ἀσὰ δὲ ἐγέννησε τὸν Ἰωσαφάτ, Ἰωσαφὰτ δὲ ἐγέννησε τὸν Ἰωράμ, Ἰωρὰμ δὲ ἐγέννησε τὸν Ὀζίαν,","en":"Asa fathered Jehoshaphat, Jehoshaphat fathered Joram, and Joram fathered Uzziah.","ko":"아사는 여호사밧을, 여호사밧은 요람을, 요람은 웃시야를 낳았습니다."},{"number":9,"greek":"Ὀζίας δὲ ἐγέννησε τὸν Ἰωαθάμ, Ἰωαθὰμ δὲ ἐγέννησε τὸν Ἀχάζ, Ἀχὰζ δὲ ἐγέννησε τὸν Ἑζεκίαν,","en":"Uzziah fathered Jotham, Jotham fathered Ahaz, and Ahaz fathered Hezekiah.","ko":"웃시야는 요담을, 요담은 아하스를, 아하스는 히스기야를 낳았습니다."},{"number":10,"greek":"Ἑζεκίας δὲ ἐγέννησε τὸν Μανασσῆ, Μανασσῆς δὲ ἐγέννησε τὸν Ἀμών, Ἀμὼν δὲ ἐγέννησε τὸν Ἰωσίαν,","en":"Hezekiah fathered Manasseh, Manasseh fathered Amon, and Amon fathered Josiah.","ko":"히스기야는 므낫세를, 므낫세는 아몬을, 아몬은 요시야를 낳았습니다."},{"number":11,"greek":"Ἰωσίας δὲ ἐγέννησε τὸν Ἰεχονίαν καὶ τοὺς ἀδελφοὺς αὐτοῦ ἐπὶ τῆς μετοικεσίας Βαβυλῶνος.","en":"Josiah fathered Jeconiah and his brothers at the time of the deportation to Babylon.","ko":"요시야는 바빌론으로 옮겨질 무렵 여고냐와 그의 형제들을 낳았습니다."},{"number":12,"greek":"Μετὰ δὲ τὴν μετοικεσίαν Βαβυλῶνος Ἰεχονίας ἐγέννησε τὸν Σαλαθιήλ, Σαλαθιὴλ δὲ ἐγέννησε τὸν Ζοροβαβέλ,","en":"After the deportation to Babylon, Jeconiah fathered Shealtiel, and Shealtiel fathered Zerubbabel.","ko":"바빌론으로 옮겨진 뒤 여고냐는 스알디엘을, 스알디엘은 스룹바벨을 낳았습니다."},{"number":13,"greek":"Ζοροβαβὲλ δὲ ἐγέννησε τὸν Ἀβιούδ, Ἀβιοὺδ δὲ ἐγέννησε τὸν Ἐλιακείμ, Ἐλιακεὶμ δὲ ἐγέννησε τὸν Ἀζώρ,","en":"Zerubbabel fathered Abiud, Abiud fathered Eliakim, and Eliakim fathered Azor.","ko":"스룹바벨은 아비훗을, 아비훗은 엘리아김을, 엘리아김은 아소르를 낳았습니다."},{"number":14,"greek":"Ἀζὼρ δὲ ἐγέννησε τὸν Σαδώκ, Σαδὼκ δὲ ἐγέννησε τὸν Ἀχείμ, Ἀχεὶμ δὲ ἐγέννησε τὸν Ἐλιούδ,","en":"Azor fathered Zadok, Zadok fathered Achim, and Achim fathered Eliud.","ko":"아소르는 사독을, 사독은 아킴을, 아킴은 엘리웃을 낳았습니다."},{"number":15,"greek":"Ἐλιοὺδ δὲ ἐγέννησε τὸν Ἐλεάζαρ, Ἐλεάζαρ δὲ ἐγέννησε τὸν Ματθάν, Ματθὰν δὲ ἐγέννησε τὸν Ἰακώβ,","en":"Eliud fathered Eleazar, Eleazar fathered Matthan, and Matthan fathered Jacob.","ko":"엘리웃은 엘르아살을, 엘르아살은 맛단을, 맛단은 야곱을 낳았습니다."},{"number":16,"greek":"Ἰακὼβ δὲ ἐγέννησε τὸν Ἰωσὴφ τὸν ἄνδρα Μαρίας, ἐξ ἧς ἐγεννήθη Ἰησοῦς ὁ λεγόμενος Χριστός.","en":"Jacob fathered Joseph, the husband of Mary, from whom Jesus, who is called Christ, was born.","ko":"야곱은 마리아의 남편 요셉을 낳았으며, 마리아에게서 그리스도라 불리는 예수가 태어났습니다."},{"number":17,"greek":"Πᾶσαι οὖν αἱ γενεαὶ ἀπὸ Ἀβραὰμ ἕως Δαβὶδ γενεαὶ δεκατέσσαρες, καὶ ἀπὸ Δαβὶδ ἕως τῆς μετοικεσίας Βαβυλῶνος γενεαὶ δεκατέσσαρες, καὶ ἀπὸ τῆς μετοικεσίας Βαβυλῶνος ἕως τοῦ Χριστοῦ γενεαὶ δεκατέσσαρες.","en":"Thus all the generations from Abraham to David were fourteen, from David to the deportation to Babylon fourteen, and from the deportation to Babylon to Christ fourteen.","ko":"그러므로 아브라함부터 다윗까지 열네 대, 다윗부터 바빌론 이주까지 열네 대, 바빌론 이주부터 그리스도까지 열네 대입니다."},{"number":18,"greek":"Τοῦ δὲ Ἰησοῦ Χριστοῦ ἡ γέννησις οὕτως ἦν. Μνηστευθείσης γὰρ τῆς μητρὸς αὐτοῦ Μαρίας τῷ Ἰωσήφ, πρὶν ἢ συνελθεῖν αὐτούς, εὑρέθη ἐν γαστρὶ ἔχουσα ἐκ Πνεύματος Ἁγίου.","en":"The birth of Jesus Christ happened in this way: his mother Mary was betrothed to Joseph, and before they came together she was found to be with child from the Holy Spirit.","ko":"예수 그리스도의 탄생은 이러했습니다. 어머니 마리아가 요셉과 약혼한 뒤 함께 살기 전에 성령으로 잉태한 사실이 드러났습니다."},{"number":19,"greek":"Ἰωσὴφ δὲ ὁ ἀνὴρ αὐτῆς, δίκαιος ὢν καὶ μὴ θέλων αὐτὴν παραδειγματίσαι, ἐβουλήθη λάθρᾳ ἀπολῦσαι αὐτήν.","en":"Joseph her husband, being righteous and unwilling to expose her publicly, decided to release her quietly.","ko":"마리아의 남편 요셉은 의로운 사람이었고 마리아를 공개적으로 드러내고 싶지 않아 조용히 관계를 정리하려 했습니다."},{"number":20,"greek":"Ταῦτα δὲ αὐτοῦ ἐνθυμηθέντος, ἰδού, ἄγγελος Κυρίου κατʼ ὄναρ ἐφάνη αὐτῷ, λέγων, Ἰωσὴφ υἱὸς Δαβίδ, μὴ φοβηθῇς παραλαβεῖν Μαριὰμ τὴν γυναῖκά σου, τὸ γὰρ ἐν αὐτῇ γεννηθὲν ἐκ Πνεύματός ἐστιν Ἁγίου.","en":"While he was considering these things, an angel of the Lord appeared to him in a dream and said: Joseph, son of David, do not fear to take Mary as your wife, for what is conceived in her is from the Holy Spirit.","ko":"요셉이 이런 일을 생각하고 있을 때 주의 천사가 꿈에 나타나 말했습니다. 다윗의 자손 요셉아, 마리아를 아내로 맞이하기를 두려워하지 말아라. 그에게 잉태된 것은 성령으로 말미암은 것이다."},{"number":21,"greek":"Τέξεται δὲ υἱὸν καὶ καλέσεις τὸ ὄνομα αὐτοῦ Ἰησοῦν, αὐτὸς γὰρ σώσει τὸν λαὸν αὐτοῦ ἀπὸ τῶν ἁμαρτιῶν αὐτῶν.","en":"She will bear a son, and you shall call his name Jesus, for he will save his people from their sins.","ko":"마리아가 아들을 낳을 것이니 이름을 예수라 하십시오. 그가 자기 백성을 그들의 죄에서 구원할 것이기 때문입니다."},{"number":22,"greek":"Τοῦτο δὲ ὅλον γέγονεν ἵνα πληρωθῇ τὸ ῥηθὲν ὑπὸ τοῦ Κυρίου διὰ τοῦ προφήτου, λέγοντος,","en":"All this happened so that what the Lord had spoken through the prophet might be fulfilled:","ko":"이 모든 일은 주께서 예언자를 통해 하신 말씀이 이루어지도록 일어났습니다."},{"number":23,"greek":"Ἰδού, ἡ παρθένος ἐν γαστρὶ ἕξει καὶ τέξεται υἱόν, καὶ καλέσουσι τὸ ὄνομα αὐτοῦ Ἐμμανουήλ, ὅ ἐστι μεθερμηνευόμενον, Μεθʼ ἡμῶν ὁ Θεός.","en":"Behold, the virgin will conceive and bear a son, and they will call his name Emmanuel, which means God with us.","ko":"보십시오. 처녀가 잉태하여 아들을 낳을 것이며 사람들은 그 이름을 임마누엘이라 부를 것입니다. 그 뜻은 하나님이 우리와 함께 계시다는 것입니다."},{"number":24,"greek":"Διεγερθεὶς δὲ ὁ Ἰωσὴφ ἀπὸ τοῦ ὕπνου ἐποίησεν ὡς προσέταξεν αὐτῷ ὁ ἄγγελος Κυρίου καὶ παρέλαβε τὴν γυναῖκα αὐτοῦ,","en":"When Joseph awoke from sleep, he did as the angel of the Lord had commanded him and took his wife.","ko":"요셉은 잠에서 깨어나 주의 천사가 명령한 대로 마리아를 아내로 맞이했습니다."}];
